mapper.select:
SELECT EXISTS(
SELECT 1 FROM category WHERE name = #{name} AND is_deleted = 0 LIMIT 1
)

mapper.update:
UPDATE category
SET is_deleted = 1, updated_at = now(), updated_by = #{updatedBy}
WHERE category_id = #{categoryId} AND is_deleted = 0

UPDATE category
SET is_deleted = 0, updated_at = now(), updated_by = #{updatedBy}
WHERE category_id = #{categoryId} AND is_deleted = 1

UPDATE category
SET is_active = #{isActive}, updated_at = now(), updated_by = #{updatedBy}
WHERE category_id = #{categoryId} AND is_deleted = 0
